import type { NextConfig } from "next";

/**
 * Next.js configuration.
 *
 * Note for beginners: the starter template turned on "Cache Components" and
 * "partial prefetching". Those are advanced performance features that force
 * every logged-in page to be wrapped in <Suspense>. Stockora is a logged-in
 * business app where every page depends on who you are, so we keep the simpler
 * default behaviour. We can revisit this when we optimise performance (Phase 6).
 */
const nextConfig: NextConfig = {
  // Tailwind CSS v4 loader for Turbopack (generated by create-next-app).
  turbopack: {
    rules: {
      "*.css": {
        loaders: ["@tailwindcss/turbopack"],
        as: "*.css",
      },
    },
  },
};

export default nextConfig;
